/*
 * A087815  Terms in A087816 that occur in a run of length more than 1.
 * https://oeis.org/A087815
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn
 * Formula:   values v of A087816 (a(n)=a(a(n-1))+a(n-1-a(n-1)), a(1)=a(2)=1)
 *            that occur in a run of length >1; generated by simulating
 *            A087816
 * Range:     u8 n <= 65, u16 n <= 65, u32 n <= 65, u64 n <= 65, u128 n <= 65,
 *            big any n
 * Validated: partial, pass, 65 terms through n = 65 (2026-11-07)
 * Helpers:   mem
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdlib.h>
#include "../utils/mem.h"

seq_t a(idx_t n)
{
    static seq_t *s = NULL;      /* A087816 terms, 1-indexed */
    static idx_t scap = 0, L = 0;
    static seq_t *res = NULL;    /* results */
    static idx_t rcap = 0, R = 0;

    if (L == 0) {
        scap = 16;
        s = mem_new(seq_t, scap);
        rcap = 16;
        res = mem_new(seq_t, rcap);
        s[1] = (seq_t)1;
        s[2] = (seq_t)1;
        L = 2;
        res[0] = (seq_t)1;
        R = 1;
    }

    while (R < n) {
        if (L + 1 >= scap) {
            idx_t nc = scap * 2;
            seq_t *t = mem_resize(seq_t, s, nc);
            if (!t) abort();
            for (idx_t i = scap; i < nc; ++i) t[i] = 0;
            s = t;
            scap = nc;
        }
        idx_t i = L + 1;
        idx_t pv = (idx_t)s[i - 1];
        idx_t j = (i - 1) - pv;
        s[i] = s[pv] + s[j];
        L = i;
        if (s[i] == s[i - 1] && (i < 3 || s[i - 2] != s[i])) {
            if (R >= rcap) {
                idx_t nc = rcap * 2;
                seq_t *t = mem_resize(seq_t, res, nc);
                if (!t) abort();
                for (idx_t k = rcap; k < nc; ++k) t[k] = 0;
                res = t;
                rcap = nc;
            }
            res[R++] = s[i];
        }
    }
    return res[n - 1];
}
